// Define pyramid dimensions
const height = 19; // Number of levels
const baseWidth = 19; // Width of the bottom layer
const material = 'sandstone';

// Calculate center offsets to ensure the pyramid is centered on the bot's position
const centerX = world.getPosition(bot).x;
const centerY = world.getPosition(bot).y; // We will build upwards from here
const centerZ = world.getPosition(bot).z;

// Set starting coordinates relative to center to create the bounding box
// Subtracting half-width to center the box visually
const startX = centerX - Math.floor(baseWidth / 2);
const startY = centerY; // Base sits directly under/bot-level
const startZ = centerZ - Math.floor(baseWidth / 2);

// Loop through the pyramid volume using 3 nested loops
for (let y = startY; y < startY + height; y++) {
    for (let x = startX; x < startX + baseWidth; x++) {
        for (let z = startZ; z < startZ + baseWidth; z++) {

            // Calculate distance from the center of the base for this block
            const dx = x - centerX;
            const dz = z - centerZ;

            // Calculate how much the pyramid has narrowed at this specific height
            // As 'y' increases (going up), the allowable width decreases
            const currentLayerWidth = baseWidth - (y - startY);

            // If the distance in any axis exceeds the current layer's capacity, skip block
            if (Math.abs(dx) > Math.floor(currentLayerWidth / 2) || Math.abs(dz) > Math.floor(currentLayerWidth / 2)) {
                continue;
            }

            // Check if we are near the apex (last block) to ensure proper tapering
            // Avoid placing blocks if radius would be less than 1 (floating tip)
            if (currentLayerWidth < 1) {
                 if (x === centerX && z === centerZ) {
                     await skills.placeBlock(bot, material, x, y, z);
                 }
                 continue;
            }

            // Place block only if it's within the valid pyramid boundary
            // We ensure a solid filled pyramid, not just walls
            // Simple check: distance in x and z must fit within the current slice width
            if (Math.abs(dx) <= Math.floor(currentLayerWidth / 2) && Math.abs(dz) <= Math.floor(currentLayerWidth / 2)) {
                await skills.placeBlock(bot, material, x, y, z);
            }
        }
    }
}
